// Draw fish
function drawFish(x, y, size, color) {
    // Body
    ctx.fillStyle = color;
    ctx.fillRect(x, y, size, size/2);

    // Tail
    ctx.fillRect(x - size/2, y + size/4, size/2, size/2);

    // Eye
    ctx.fillStyle = '#fff';
    ctx.fillRect(x + size/3, y + size/8, 4, 4);

    // Fin
    ctx.fillStyle = '#ff6b6b';
    ctx.fillRect(x + size/3, y, 6, size/4);
}

