const centerX = 200;
const centerY = 200;
const radius = 150;

// Slice angle (12 o'clock position is 0 degrees)
const startAngle = -Math.PI/2; // bottom center
const endAngle = -Math.PI/6;   // about 30 degrees clockwise

// Create gradient for pizza slice
const gradient = ctx.createLinearGradient(
  centerX - radius, centerY - radius,
  centerX + radius, centerY + radius
);
gradient.addColorStop(0, '#ff6b35'); // red
gradient.addColorStop(1, '#ff8e9b'); // pink

// Draw pizza slice
ctx.fillStyle = gradient;
ctx.beginPath();
ctx.moveTo(centerX, centerY);
ctx.arc(centerX, centerY, radius, startAngle, endAngle, false);
ctx.closePath();
ctx.fill();

