const centerX = W / 2;
const centerY = H / 2;
const maxRadius = Math.min(W, H) / 2 - 20;

// Draw spiral with cool tones
function drawSpiral(radius, angle) {
    if (radius > maxRadius) return;

    const x = centerX + Math.cos(angle) * radius;
    const y = centerY + Math.sin(angle) * radius;

    // Adjust tone based on radius
    const tone = 20 + Math.floor(40 * (1 - radius / maxRadius));
    ctx.fillStyle = `hsl(200, 100%, ${tone}%)`;

    // Draw arc segment
    ctx.beginPath();
    ctx.arc(x, y, 2, 0, Math.PI * 2);
    ctx.fill();

    // Recursive call for next segment
    drawSpiral(radius + 2, angle + 0.03);
}

// Start spiral at center
drawSpiral(0, 0);

// Add some gradient effect
for (let r = 10; r < maxRadius; r += 10) {
    const angle = r / maxRadius * Math.PI;
    const x = centerX + Math.cos(angle) * r;
    const y = centerY + Math.sin(angle) * r;

    const tone = 10 + Math.floor(30 * (1 - r / maxRadius));
    ctx.fillStyle = `hsl(200, 100%, ${tone}%)`;
    ctx.beginPath();
    ctx.arc(x, y, 3, 0, Math.PI * 2);
    ctx.fill();
}

