ctx.fillStyle = '#8B4513';
let centerX = 200;
let centerY = 200;
let radius = 0;
const steps = 20;
const angleStep = Math.PI / 6;

for (let i = 0; i < steps; i++) {
    radius += 10;
    const x1 = centerX + Math.cos(angleStep * i) * radius;
    const y1 = centerY + Math.sin(angleStep * i) * radius;

    if (i > 0) {
        ctx.beginPath();
        ctx.moveTo(x1, y1);
        ctx.lineTo(x1 - Math.cos(angleStep * (i - 1)) * 5, 
                   y1 - Math.sin(angleStep * (i - 1)) * 5);
        ctx.strokeStyle = '#A0522D';
        ctx.lineWidth = 3;
        ctx.stroke();
    }

    ctx.beginPath();
    ctx.arc(x1, y1, 8, 0, Math.PI * 2);
    ctx.fillStyle = '#8B4513';
    ctx.fill();
}

// Shell details
ctx.fillStyle = '#654321';
for (let i = 0; i < 8; i++) {
    const angle = (i / 8) * Math.PI * 2;
    const x = centerX + Math.cos(angle) * (radius + 15);
    const y = centerY + Math.sin(angle) * (radius + 15);
    ctx.beginPath();
    ctx.arc(x, y, 5, 0, Math.PI * 2);
    ctx.fill();
}

// Shell spiral lines
ctx.strokeStyle = '#A0522D';
ctx.lineWidth = 2;
for (let i = 0; i < steps - 1; i++) {
    const x1 = centerX + Math.cos(angleStep * i) * radius;
    const y1 = centerY + Math.sin(angleStep * i) * radius;
    const x2 = centerX + Math.cos(angleStep * (i + 1)) * (radius + 10);
    const y2 = centerY + Math.sin(angleStep * (i + 1)) * (radius + 10);
    ctx.beginPath();
    ctx.moveTo(x1, y1);
    ctx.lineTo(x2, y2);
    ctx.stroke();
}

